import { screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it } from "vitest";
import { MockApi } from "../api/mock/MockApi";
import { renderApp } from "./utils";

// Homebrew WB-22 (spec 11, 12.3): copies on the mock, which serves the real backend's copies of the SRD Fireball and the
// 2024 Wizard (`homebrew-copies.ts`, generated by src-tauri/tests/homebrew_copy.rs). "Start from a template" lists SRD
// elements only; the copy is named "<Name> (copy)" with the name selected for renaming; a class copies its features and
// subclasses too; "Copy to homebrew" in the Compendium copies into a pack and opens the copy.

const nameBox = () => screen.getByRole("textbox", { name: /^Name/ }) as HTMLInputElement;

async function workspace(user: ReturnType<typeof userEvent.setup>) {
  const api = new MockApi({ creatorEnabled: true });
  const pack = await api.homebrewCreatePack({ request: { name: "Ember Isles", code: "EMB", edition: "dnd2024" } });
  renderApp(`/homebrew/${pack.id}`, { api });
  await user.click(await screen.findByRole("button", { name: "New element" }));
  return { api, pack, flyout: await screen.findByRole("dialog", { name: "New element" }) };
}

describe("WB-22 copies (mock)", () => {
  it("a template copy of the SRD Fireball: SRD rows only, '(copy)' selected for renaming, edited and saved", async () => {
    const user = userEvent.setup();
    const { api, flyout } = await workspace(user);
    await user.click(within(flyout).getByRole("radio", { name: /^Spell A spell/ }));
    await user.click(within(flyout).getByRole("radio", { name: /^Start from a template/ }));
    await user.click(within(flyout).getByRole("button", { name: "Choose..." }));
    const picker = await screen.findByRole("dialog", { name: /Spell template/ });
    await user.click(await within(picker).findByRole("button", { name: /Fireball/ }));
    await user.click(within(picker).getByRole("button", { name: "Choose" }));
    await waitFor(() => expect(nameBox().value).toBe("Fireball (copy)"));
    await waitFor(() => expect(document.activeElement).toBe(nameBox()));
    expect([nameBox().selectionStart, nameBox().selectionEnd]).toEqual([0, "Fireball (copy)".length]);
    await user.clear(nameBox());
    await user.type(nameBox(), "Emberball");
    await user.click(screen.getByRole("button", { name: "Save" }));
    expect(await screen.findByRole("button", { name: "Emberball" })).toBeTruthy();
    const rows = await api.homebrewReferenceOptions({ target: { types: ["Spell"] }, query: "", filters: { srdOnly: true }, page: { offset: 0, limit: 10 } });
    expect(rows.items.map((r) => r.name)).toEqual(["Fireball"]);
  });

  it("a deep copy of the SRD Wizard saves its subclass with it", async () => {
    const user = userEvent.setup();
    const { api, pack, flyout } = await workspace(user);
    await user.click(within(flyout).getByRole("radio", { name: /^Class A class/ }));
    await user.click(within(flyout).getByRole("radio", { name: /^New from copy/ }));
    const deep = within(flyout).getByRole("checkbox", { name: "Copy its features and subclasses too" }) as HTMLInputElement;
    expect(deep.checked).toBe(true);
    await user.click(within(flyout).getByRole("button", { name: "Choose..." }));
    const picker = await screen.findByRole("dialog", { name: /Class to copy/ });
    // the SRD Wizard (the mock's sample content has a Wizard too): its source is the user's own label for it
    const wizard = await within(picker).findByRole("button", { name: /Wizard.*SRD 5\.2\.1/ });
    await user.click(wizard);
    await user.click(within(picker).getByRole("button", { name: "Choose" }));
    await waitFor(() => expect(nameBox().value).toBe("Wizard (copy)"));
    // the class editor names the subclasses saved with it (board Hy6vY)
    expect(within(screen.getByRole("region", { name: "Element editor" })).getByRole("note", { name: "Saved with it" }).textContent)
      .toBe("Saved with it: Evoker.");
    await user.click(screen.getByRole("button", { name: "Save" }));
    await waitFor(async () => {
      const kinds = (await api.homebrewListElements({ packId: pack.id })).map((e) => `${e.kind}:${e.name}`);
      expect(kinds).toEqual(["class:Wizard (copy)", "subclass:Evoker"]);
    });
  });

  it("Copy to homebrew in the Compendium copies into a pack and opens the copy", async () => {
    const user = userEvent.setup();
    const api = new MockApi({ creatorEnabled: true });
    const pack = await api.homebrewCreatePack({ request: { name: "Ember Isles", code: "EMB", edition: "dnd2024" } });
    renderApp("/characters", { api });
    await user.type(await screen.findByLabelText("Compendium search"), "unicorn{Enter}");
    const dlg = await screen.findByRole("dialog", { name: "Compendium" });
    await user.click(await within(dlg).findByRole("button", { name: /Unicorn/ }));
    await user.click(await within(dlg).findByRole("link", { name: "Copy to homebrew" }));
    const copy = await screen.findByRole("dialog", { name: "Copy to homebrew" });
    expect((within(copy).getByRole("combobox", { name: "Pack" }) as HTMLSelectElement).value).toBe(pack.id);
    await user.click(within(copy).getByRole("button", { name: "Copy" }));
    await waitFor(() => expect(nameBox().value).toBe("Unicorn (copy)"));
    expect(screen.queryByRole("dialog", { name: "Compendium" })).toBeNull();
  });

  it("with no homebrew pack, Copy to homebrew offers to make one", async () => {
    const user = userEvent.setup();
    renderApp("/characters", { api: new MockApi({ creatorEnabled: true }) });
    await user.type(await screen.findByLabelText("Compendium search"), "unicorn{Enter}");
    const dlg = await screen.findByRole("dialog", { name: "Compendium" });
    await user.click(await within(dlg).findByRole("button", { name: /Unicorn/ }));
    await user.click(await within(dlg).findByRole("link", { name: "Copy to homebrew" }));
    const copy = await screen.findByRole("dialog", { name: "Copy to homebrew" });
    expect(await within(copy).findByText(/You have no homebrew pack yet/)).toBeTruthy();
    await user.click(within(copy).getByRole("button", { name: "New pack" }));
    expect(await screen.findByRole("dialog", { name: "New pack" })).toBeTruthy();
  });
});
